// describe_word() is Mesa 26.2.1's va_disasm_instr (generated by
// src/panfrost/compiler/bifrost/valhall/disasm.py) as an interpreter of the
// print steps in v10.rs (MIT). The upstream part stays under its licence
// (LICENSES/MIT.txt); our changes are Apache-2.0. See NOTICE.
//! The Valhall v10 (Mali-G610) instruction set: a 64-bit word per
//! instruction, encoded, decoded and disassembled.
//!
//! The table is [`v10`], GENERATED by tools/mali/gen_isa_rs.py from Arm's
//! isa-v9-v14.xml (Mesa 26.2.1, `src/panfrost/compiler/kraid/`): one [`Op`]
//! per `<instruction>` valid for arch 10. An [`Instr`] is an op and the values
//! of its operands: the fields the XML leaves free and the virtual operands
//! that its expressions read. The fields the XML computes (a staging
//! register count from the vector size, an encoded table index from the
//! table index, ...) are not operands; the encoder computes them and the
//! decoder checks them.
//!
//! The contract is "correct or refused":
//!
//! * [`encode`] refuses a value that does not fit its field, an enum value
//!   the XML does not name or the field does not allow, an `align(n)` value
//!   that is not a multiple of n, a `shr(n)` value with any of its low n bits
//!   set, a `minus(n)` value below n, a signed value outside its field, a
//!   computed field whose value does not fit, and an expression that would
//!   underflow or overflow. Nothing is masked. Every word it writes is
//!   decoded again ([`decode_as`]) and must give the same `Instr` back.
//! * [`decode`] accepts a word only if exactly one non-alias op's opcode bits
//!   match (the generator proves that no two can), its `type="zero"` reserved
//!   bits are zero, every free field holds a value its type admits, and
//!   every computed field holds what the expression gives (also where the
//!   hardware may not read it: LOAD's `encoded_extend` when no lane is
//!   loaded). The `type="ignore"` bits, which the hardware does not read, are
//!   kept as they stand ([`Instr::ignored`]): Mesa's test vectors set some (the
//!   texture instructions' register type at 26..27, which Arm's XML marks
//!   ignored for v10), and the word must come back byte-equal. An alias
//!   (`MOV_IMM` of `IADD_IMM`, `FMUL` of `FMA`, ...) is never the answer of
//!   [`decode`]; [`decode_as`] reads a word as a given op, alias or not.
//! * [`describe_word`] prints one instruction the way Mesa 26.2.1's
//!   disassembler does (`va_disasm_instr`), from Mesa's own ISA.xml, so that
//!   our listing and Mesa's can be compared line for line. It is the second
//!   reading of the ISA and does not depend on the first: it reads the word.
//!   50 of the 365 ops are instructions Mesa's ISA.xml does not list (the
//!   rotates, DOORBELL, ...); their words are [`DescribeError::Unknown`].
//!
//! The gates (`tests`): every instruction of the board's shader binaries
//! (tools/mali/isa-ref/, Mesa 25.0.7 on the NanoPC-T6) and every vector of
//! Mesa's valhall/test/assembler-cases.txt is described as Mesa 26.2.1
//! describes it, and decodes and re-encodes byte-equal but for one named
//! word of each; the board text differs from Mesa 26.2.1's by three named
//! rules of presentation, and on the MKVEC word by the bit 27 the two Mesa
//! versions read differently; every variant encodes a word that decodes back to
//! it; the variant count equals the XML's.
//!
//! Nothing here selects, schedules or allocates: the back end
//! (`super::compile_linked_blocks`) still refuses every shader.

pub mod v10;

#[cfg(test)]
mod tests;

use core::fmt;
pub use v10::{Op, MAX_OPERANDS, MAX_SYMBOLS, OPS, VARIANTS};

/// Which unit runs the instruction (`exec_unit`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Unit {
    Fma,
    Cvt,
    Sfu,
    /// A message: the instruction leaves the core (loads, stores, varyings,
    /// textures, ATEST, BLEND).
    Msg,
}

/// An enum of the XML (`<enum>` for arch 10): its names and the raw values
/// that are valid. A raw value can have more than one name (the values the
/// XML marks `canonical="0"`).
#[derive(Debug)]
pub struct EnumInfo {
    pub name: &'static str,
    pub values: &'static [(&'static str, u32)],
    /// The distinct values, ascending.
    pub valid: &'static [u32],
}

impl EnumInfo {
    /// The raw value of a name.
    pub fn value(&self, name: &str) -> Option<u32> {
        self.values.iter().find(|(n, _)| *n == name).map(|&(_, v)| v)
    }
    /// The first name of a raw value.
    pub fn name_of(&self, value: u32) -> Option<&'static str> {
        self.values.iter().find(|&&(_, v)| v == value).map(|&(n, _)| n)
    }
}

/// What a field or a virtual holds.
#[derive(Clone, Copy, Debug)]
pub enum Kind {
    /// One of the enum's values.
    Enum(&'static EnumInfo),
    /// An unsigned value of `bits` bits (after the field's modifier).
    Uint { bits: u32 },
    /// A two's-complement value of `bits` bits, held in the `u32` as the
    /// bits of an `i32`.
    Int { bits: u32 },
    /// A source operand, 8 bits: a register (`0..63`, bit 6 the discard
    /// flag), a uniform (`0x80 | slot`) or an immediate (`0xC0 | index`).
    Source,
    /// The same, naming a 64-bit register pair or uniform.
    Source64,
}

/// A field's modifier (isa-v9-v14.xml `modifier=`; Kraid's FieldMod).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Modifier {
    /// The field holds the value, which must be a multiple of n.
    Align(u32),
    /// The field holds the value shifted right by n; the low n bits must
    /// be zero.
    Shr(u32),
    /// The field holds the value minus n.
    Minus(u32),
}

/// Where a symbol's value comes from.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SymKind {
    /// The XML's `exact=`: part of the opcode (a field) or a constant (a
    /// virtual).
    Exact(u32),
    /// An expression of the other symbols (only fields).
    Computed,
    /// The `Instr`'s operand of this index.
    Operand(usize),
}

/// A field (`field: Some((pos, width))`) or a virtual (`None`) of one op.
#[derive(Debug)]
pub struct Sym {
    pub name: &'static str,
    pub field: Option<(u32, u32)>,
    pub modifier: Option<Modifier>,
    pub kind: Kind,
    /// The XML's `restrict=`: the enum values this op allows.
    pub restrict: Option<&'static [u32]>,
    /// The XML's `min=`/`max=`.
    pub range: Option<(u32, u32)>,
    pub what: SymKind,
}

impl Sym {
    /// A field at `pos`, `width` bits (the generated table's constructors).
    pub(crate) const fn field(name: &'static str, pos: u32, width: u32, kind: Kind, what: SymKind) -> Sym {
        Sym { name, field: Some((pos, width)), modifier: None, kind, restrict: None, range: None, what }
    }
    /// A virtual.
    pub(crate) const fn virt(name: &'static str, kind: Kind, what: SymKind) -> Sym {
        Sym { name, field: None, modifier: None, kind, restrict: None, range: None, what }
    }
    pub(crate) const fn modifier(self, m: Modifier) -> Sym {
        Sym { modifier: Some(m), ..self }
    }
    pub(crate) const fn restrict(self, r: &'static [u32]) -> Sym {
        Sym { restrict: Some(r), ..self }
    }
    pub(crate) const fn range(self, min: u32, max: u32) -> Sym {
        Sym { range: Some((min, max)), ..self }
    }
}

/// What an operand is in the instruction's syntax (isa-v9-v14.xml
/// `<syntax>`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Role {
    Dest,
    Src,
    /// A staging register base (`staging_register_index`,
    /// `staging_register_write_index`).
    Staging,
    /// A modifier of the name, the destination or a source.
    Modifier,
    /// An immediate of the syntax (`offset`, `index`, `imm1w`, ...).
    Immediate,
    /// The flow-control field (waits, `.end`, ...).
    Flow,
    /// The FAU page of the uniform sources.
    FauPage,
    /// A field the syntax does not name (a staging count the syntax implies,
    /// a register-control field, ...).
    Other,
}

/// One operand of an op: an index into its symbols.
#[derive(Debug)]
pub struct Operand {
    pub name: &'static str,
    pub sym: usize,
    pub role: Role,
    /// The XML's `default=`. Named unmeasured: 774 of the 970 operand
    /// defaults never appear in the corpus (the board's binaries and Mesa's
    /// vectors); `builder_defaults_are_checked_against_the_corpus` derives
    /// the numbers and pins them (970 total, 196 exercised and held).
    pub default: Option<u32>,
}

/// The evaluation of an expression of the XML that the encoder refuses
/// rather than wraps.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ExprError {
    /// `sub` below zero.
    Underflow,
    /// `add` or `lshift` past 32 bits.
    Overflow,
    /// A shift, or a `mask`, of 32 bits or more.
    ShiftTooFar,
}

pub(crate) fn add(a: u32, b: u32) -> Result<u32, ExprError> {
    a.checked_add(b).ok_or(ExprError::Overflow)
}
pub(crate) fn sub(a: u32, b: u32) -> Result<u32, ExprError> {
    a.checked_sub(b).ok_or(ExprError::Underflow)
}
pub(crate) fn shr(a: u32, b: u32) -> Result<u32, ExprError> {
    a.checked_shr(b).ok_or(ExprError::ShiftTooFar)
}
pub(crate) fn shl(a: u32, b: u32) -> Result<u32, ExprError> {
    let r = a.checked_shl(b).ok_or(ExprError::ShiftTooFar)?;
    if r >> b != a {
        return Err(ExprError::Overflow);
    }
    Ok(r)
}
pub(crate) fn mask(bits: u32) -> Result<u32, ExprError> {
    match bits {
        32 => Ok(u32::MAX),
        b if b < 32 => Ok((1u32 << b) - 1),
        _ => Err(ExprError::ShiftTooFar),
    }
}

/// The expressions of one op over its symbols' values.
pub type ExprFn = fn(&mut [u32; MAX_SYMBOLS]) -> Result<(), ExprError>;

/// One op of the table.
#[derive(Debug)]
pub struct OpInfo {
    pub op: Op,
    /// `NAME.variant`, the XML's.
    pub mnemonic: &'static str,
    pub name: &'static str,
    pub variant: Option<&'static str>,
    /// The op this one is an alias of (the XML's `alias=`).
    pub alias_of: Option<Op>,
    pub unit: Unit,
    /// The `<instruction>`'s line in isa-v9-v14.xml.
    pub line: u32,
    /// The opcode: the exact fields.
    pub exact_mask: u64,
    pub exact_bits: u64,
    /// `<reserved type="zero">` and `type="ignore"`.
    pub zero_mask: u64,
    pub ignore_mask: u64,
    /// Fields and virtuals, in XML order.
    pub syms: &'static [Sym],
    pub operands: &'static [Operand],
    /// The virtuals' expressions (they read fields).
    pub virtuals: Option<ExprFn>,
    /// The computed fields' expressions (they read operands).
    pub computed: Option<ExprFn>,
}

impl Op {
    pub fn info(self) -> &'static OpInfo {
        &OPS[self as usize]
    }
}

/// An instruction: an op and its operands' values, in the order of
/// [`OpInfo::operands`]; the slots past them are zero.
#[derive(Clone, Copy, PartialEq, Eq)]
pub struct Instr {
    pub op: Op,
    pub vals: [u32; MAX_OPERANDS],
    /// The word's bits under the op's `ignore_mask`, in place (zero for an
    /// instruction built here).
    pub ignored: u64,
}

impl Instr {
    /// The op with each operand at the XML's `default=` (named unmeasured:
    /// 774 of the 970 defaults never appear in the corpus, see
    /// [`Operand::default`]), and the operands that have none at zero (which [`encode`] may refuse: zero is not a
    /// value of every enum).
    pub fn new(op: Op) -> Instr {
        let mut vals = [0; MAX_OPERANDS];
        for (i, o) in op.info().operands.iter().enumerate() {
            vals[i] = o.default.unwrap_or(0);
        }
        Instr { op, vals, ignored: 0 }
    }

    fn slot(&self, name: &str) -> Option<usize> {
        self.op.info().operands.iter().position(|o| o.name == name)
    }

    /// An operand's value by its XML name.
    pub fn get(&self, name: &str) -> Option<u32> {
        self.slot(name).map(|i| self.vals[i])
    }

    /// Set an operand by its XML name; `None` if the op has no such operand.
    /// The value is checked by [`encode`].
    pub fn set(&mut self, name: &str, v: u32) -> Option<()> {
        let i = self.slot(name)?;
        self.vals[i] = v;
        Some(())
    }
}

impl fmt::Debug for Instr {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let info = self.op.info();
        write!(f, "{}", info.mnemonic)?;
        for (i, o) in info.operands.iter().enumerate() {
            write!(f, " {}={:#x}", o.name, self.vals[i])?;
        }
        for (i, v) in self.vals.iter().enumerate().skip(info.operands.len()) {
            if *v != 0 {
                write!(f, " [{i}]={v:#x}")?;
            }
        }
        if self.ignored != 0 {
            write!(f, " ignored={:#x}", self.ignored)?;
        }
        Ok(())
    }
}

/// Why a value does not go into, or does not come out of, its field.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Why {
    /// More bits than the field has (after its modifier).
    TooWide { value: u32, bits: u32 },
    /// A signed value outside the field's range.
    IntOutOfRange { value: i64, bits: u32 },
    /// A value the enum does not name.
    NotNamed { value: u32, enumeration: &'static str },
    /// A named value this op's `restrict=` does not allow.
    NotAllowed { value: u32 },
    /// Outside `min=`..`max=`.
    OutOfRange { value: u32, min: u32, max: u32 },
    /// `align(n)`: not a multiple of n.
    NotAligned { value: u32, align: u32 },
    /// `shr(n)`: low bits set.
    LowBitsSet { value: u32, shift: u32 },
    /// `minus(n)`: below n.
    BelowMinus { value: u32, minus: u32 },
    /// A 64-bit source naming an odd register or uniform byte (Kraid's
    /// `encoded & 1 == 0`; only a small constant, 0xC0..=0xDF, may be odd).
    OddSource64 { value: u32 },
    /// A special (type 3) source of 0xE0 or more on FAU page 2, which Mesa
    /// prints as `reserved_page2`.
    ReservedFauPage2 { value: u32 },
}

/// Why a word was not decoded.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DecodeError {
    /// No non-alias op's opcode bits match the word.
    Unknown { word: u64 },
    /// [`decode_as`]: the word's opcode bits are not this op's.
    NotThisOp { op: Op },
    /// Bits the XML reserves as zero are set.
    ReservedBitsSet { op: Op, bits: u64 },
    /// A field, or a virtual, holds a value its type does not admit.
    Field { op: Op, field: &'static str, why: Why },
    /// An expression of the XML cannot be evaluated on this word.
    Expr { op: Op, err: ExprError },
    /// A computed field holds another value than its expression gives.
    Inconsistent { op: Op, field: &'static str, word: u32, expected: u32 },
}

/// Why an instruction was not encoded.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EncodeError {
    /// A slot past the op's operands is not zero.
    UnusedSlot { op: Op, slot: usize },
    /// [`Instr::ignored`] has bits outside the op's `ignore_mask`.
    IgnoredOutsideMask { op: Op, bits: u64 },
    /// An operand, or a computed field, does not fit.
    Field { op: Op, field: &'static str, why: Why },
    /// An expression of the XML cannot be evaluated on these operands.
    Expr { op: Op, err: ExprError },
    /// The word decodes as this op with other operand values (a virtual
    /// operand whose fields give another value back).
    ReadsBackAs { op: Op },
    /// The word does not decode as this op (only a defect could do this).
    DoesNotDecode(DecodeError),
}

fn bits_of(w: u64, pos: u32, width: u32) -> u32 {
    ((w >> pos) & ((1u64 << width) - 1)) as u32
}

/// A field's raw bits to its value (the modifier undone). Signed fields
/// are sign-extended; the `u32` holds the `i32`'s bits.
fn field_value(s: &Sym, raw: u32, width: u32) -> u32 {
    if let Kind::Int { .. } = s.kind {
        let mut v = i64::from(raw);
        if raw >> (width - 1) & 1 == 1 {
            v -= 1i64 << width;
        }
        v = match s.modifier {
            Some(Modifier::Shr(n)) => v << n,
            Some(Modifier::Minus(n)) => v + i64::from(n),
            _ => v,
        };
        return v as i32 as u32;
    }
    match s.modifier {
        Some(Modifier::Shr(n)) => raw << n,
        Some(Modifier::Minus(n)) => raw + n,
        _ => raw,
    }
}

/// A value to a field's raw bits, refusing what does not fit.
fn field_raw(s: &Sym, v: u32, width: u32) -> Result<u32, Why> {
    if let Kind::Int { bits } = s.kind {
        let mut x = i64::from(v as i32);
        match s.modifier {
            Some(Modifier::Align(n)) if x % i64::from(n) != 0 => return Err(Why::NotAligned { value: v, align: n }),
            Some(Modifier::Shr(n)) => {
                if x & ((1i64 << n) - 1) != 0 {
                    return Err(Why::LowBitsSet { value: v, shift: n });
                }
                x >>= n;
            }
            Some(Modifier::Minus(n)) => x -= i64::from(n),
            _ => {}
        }
        if x < -(1i64 << (width - 1)) || x >= 1i64 << (width - 1) {
            return Err(Why::IntOutOfRange { value: i64::from(v as i32), bits });
        }
        return Ok((x as u64 & ((1u64 << width) - 1)) as u32);
    }
    let mut x = v;
    match s.modifier {
        Some(Modifier::Align(n)) if !x.is_multiple_of(n) => return Err(Why::NotAligned { value: v, align: n }),
        Some(Modifier::Shr(n)) => {
            if x & ((1u32 << n) - 1) != 0 {
                return Err(Why::LowBitsSet { value: v, shift: n });
            }
            x >>= n;
        }
        Some(Modifier::Minus(n)) => {
            x = x.checked_sub(n).ok_or(Why::BelowMinus { value: v, minus: n })?;
        }
        _ => {}
    }
    if u64::from(x) >> width != 0 {
        return Err(Why::TooWide { value: v, bits: width });
    }
    Ok(x)
}

/// The checks of a value against its type that do not depend on the field
/// width: enum names, `restrict=`, `min=`/`max=`, a virtual's width.
fn check_value(s: &Sym, v: u32) -> Result<(), Why> {
    match s.kind {
        Kind::Enum(e) => {
            if e.valid.binary_search(&v).is_err() {
                return Err(Why::NotNamed { value: v, enumeration: e.name });
            }
        }
        Kind::Uint { bits } if s.field.is_none() && bits < 32 && v >> bits != 0 => {
            return Err(Why::TooWide { value: v, bits });
        }
        // Kraid asserts `encoded & 1 == 0` for a 64-bit source unless it is a
        // small constant (mesa-26.2.1 kraid/encode_v9.rs:228-230).
        Kind::Source64 if v & 1 == 1 && !(0xC0..=0xDF).contains(&v) => {
            return Err(Why::OddSource64 { value: v });
        }
        _ => {}
    }
    if let Some(r) = s.restrict {
        if !r.contains(&v) {
            return Err(Why::NotAllowed { value: v });
        }
    }
    if let Some((min, max)) = s.range {
        if v < min || v > max {
            return Err(Why::OutOfRange { value: v, min, max });
        }
    }
    Ok(())
}

/// A special (type 3) source of 0xE0 or more is reserved on FAU page 2
/// (`reserved_page2` in Mesa's disassembler). Returns the field and value.
fn check_page2(info: &OpInfo, s: &[u32; MAX_SYMBOLS]) -> Result<(), (&'static str, Why)> {
    let Some(page) = info.syms.iter().position(|y| y.name == "fau_page_index") else { return Ok(()) };
    if s[page] != 2 {
        return Ok(());
    }
    for (i, y) in info.syms.iter().enumerate() {
        if matches!(y.kind, Kind::Source | Kind::Source64) && matches!(y.what, SymKind::Operand(_)) && s[i] >= 0xE0 {
            return Err((y.name, Why::ReservedFauPage2 { value: s[i] }));
        }
    }
    Ok(())
}

/// Decode a word: the one non-alias op whose opcode bits match, and its
/// operands.
pub fn decode(w: u64) -> Result<Instr, DecodeError> {
    for info in OPS.iter() {
        if info.alias_of.is_none() && w & info.exact_mask == info.exact_bits {
            return decode_as(info.op, w);
        }
    }
    Err(DecodeError::Unknown { word: w })
}

/// Decode a word as one op (an alias too).
pub fn decode_as(op: Op, w: u64) -> Result<Instr, DecodeError> {
    let info = op.info();
    if w & info.exact_mask != info.exact_bits {
        return Err(DecodeError::NotThisOp { op });
    }
    if w & info.zero_mask != 0 {
        return Err(DecodeError::ReservedBitsSet { op, bits: w & info.zero_mask });
    }
    let mut s = [0u32; MAX_SYMBOLS];
    let mut raw = [0u32; MAX_SYMBOLS];
    for (i, sym) in info.syms.iter().enumerate() {
        match (sym.field, sym.what) {
            (Some((pos, width)), what) => {
                raw[i] = bits_of(w, pos, width);
                s[i] = field_value(sym, raw[i], width);
                if let SymKind::Operand(_) = what {
                    check_value(sym, s[i]).map_err(|why| DecodeError::Field { op, field: sym.name, why })?;
                }
            }
            (None, SymKind::Exact(v)) => s[i] = v,
            (None, _) => {}
        }
    }
    if let Some(f) = info.virtuals {
        f(&mut s).map_err(|err| DecodeError::Expr { op, err })?;
        for (i, sym) in info.syms.iter().enumerate() {
            if sym.field.is_none() && matches!(sym.what, SymKind::Operand(_)) {
                check_value(sym, s[i]).map_err(|why| DecodeError::Field { op, field: sym.name, why })?;
            }
        }
    }
    check_page2(info, &s).map_err(|(field, why)| DecodeError::Field { op, field, why })?;
    if let Some(f) = info.computed {
        let mut c = s;
        f(&mut c).map_err(|err| DecodeError::Expr { op, err })?;
        for (i, sym) in info.syms.iter().enumerate() {
            if sym.what != SymKind::Computed {
                continue;
            }
            let (_, width) = sym.field.expect("a computed symbol is a field");
            let expected = field_raw(sym, c[i], width).and_then(|r| check_value(sym, c[i]).map(|()| r));
            match expected {
                Ok(e) if e == raw[i] => {}
                Ok(e) => return Err(DecodeError::Inconsistent { op, field: sym.name, word: raw[i], expected: e }),
                Err(why) => return Err(DecodeError::Field { op, field: sym.name, why }),
            }
        }
    }
    let mut vals = [0u32; MAX_OPERANDS];
    for (j, o) in info.operands.iter().enumerate() {
        vals[j] = s[o.sym];
    }
    Ok(Instr { op, vals, ignored: w & info.ignore_mask })
}

/// Encode an instruction, and check that the word decodes back to it.
pub fn encode(instr: &Instr) -> Result<u64, EncodeError> {
    let op = instr.op;
    let info = op.info();
    if let Some(slot) = (info.operands.len()..MAX_OPERANDS).find(|&i| instr.vals[i] != 0) {
        return Err(EncodeError::UnusedSlot { op, slot });
    }
    if instr.ignored & !info.ignore_mask != 0 {
        return Err(EncodeError::IgnoredOutsideMask { op, bits: instr.ignored & !info.ignore_mask });
    }
    let mut s = [0u32; MAX_SYMBOLS];
    for (i, sym) in info.syms.iter().enumerate() {
        match sym.what {
            SymKind::Exact(v) => s[i] = v,
            SymKind::Operand(j) => {
                s[i] = instr.vals[j];
                check_value(sym, s[i]).map_err(|why| EncodeError::Field { op, field: sym.name, why })?;
            }
            SymKind::Computed => {}
        }
    }
    check_page2(info, &s).map_err(|(field, why)| EncodeError::Field { op, field, why })?;
    if let Some(f) = info.computed {
        f(&mut s).map_err(|err| EncodeError::Expr { op, err })?;
    }
    let mut w = info.exact_bits | instr.ignored;
    for (i, sym) in info.syms.iter().enumerate() {
        let Some((pos, width)) = sym.field else { continue };
        if let SymKind::Exact(_) = sym.what {
            continue;
        }
        if sym.what == SymKind::Computed {
            check_value(sym, s[i]).map_err(|why| EncodeError::Field { op, field: sym.name, why })?;
        }
        let r = field_raw(sym, s[i], width).map_err(|why| EncodeError::Field { op, field: sym.name, why })?;
        w |= u64::from(r) << pos;
    }
    let back = decode_as(op, w).map_err(EncodeError::DoesNotDecode)?;
    if back != *instr {
        return Err(EncodeError::ReadsBackAs { op });
    }
    Ok(w)
}

// ---- Mesa's disassembler ----------------------------------------------------

/// How many staging registers a staging operand prints.
#[derive(Clone, Copy, Debug)]
pub enum Count {
    Fixed(u32),
    /// `((w >> start) & mask) + plus`.
    Field {
        start: u32,
        mask: u32,
        plus: u32,
    },
}

/// `va_print_float_src` (`Plain`, `AbsNeg`) or `va_print_src` (`No`).
#[derive(Clone, Copy, Debug)]
pub enum Float {
    No,
    Plain,
    AbsNeg { neg: u32, abs: u32 },
}

/// What follows a source: a lookup in one of Mesa's tables, or `.not`.
#[derive(Clone, Copy, Debug)]
pub enum Suffix {
    Table { start: u32, mask: u32, table: &'static [&'static str] },
    Not { bit: u32 },
}

/// One print step of disasm.py's `print_instr`.
#[derive(Clone, Copy, Debug)]
pub enum S {
    Text(&'static str),
    /// An enum modifier: `table[(w >> start) & mask]`.
    Table {
        start: u32,
        mask: u32,
        table: &'static [&'static str],
    },
    /// A one-bit modifier: `text` when the bit is set.
    Flag {
        start: u32,
        text: &'static str,
    },
    /// `valhall_flow[w >> 59 & 0xF]` and a space.
    Flow,
    Dest {
        size: u32,
    },
    Staging {
        start: u32,
        count: Count,
    },
    Src {
        start: u32,
        size: u32,
        float: Float,
        suffix: &'static [Suffix],
    },
    Imm {
        prefix: &'static str,
        start: u32,
        size: u32,
        signed: bool,
    },
}

/// One instruction of Mesa's ISA.xml: its opcode bits and print steps.
#[derive(Debug)]
pub struct MesaOp {
    pub name: &'static str,
    pub mask: u64,
    pub value: u64,
    pub steps: &'static [S],
}

/// Why a word was not described.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DescribeError {
    /// No instruction of Mesa's ISA.xml has these opcode bits (Mesa prints
    /// nothing).
    Unknown { word: u64 },
    /// A field indexes past the end of Mesa's print table (Mesa reads past
    /// its array).
    NoName { index: u32, len: usize },
    /// A float source names an immediate past the table (Mesa asserts).
    FloatImmediate { value: u32 },
    /// The instruction does not encode.
    Encode(EncodeError),
    /// The writer failed.
    Fmt,
}

impl From<fmt::Error> for DescribeError {
    fn from(_: fmt::Error) -> Self {
        DescribeError::Fmt
    }
}

fn name_in(table: &'static [&'static str], index: u32) -> Result<&'static str, DescribeError> {
    table.get(index as usize).copied().ok_or(DescribeError::NoName { index, len: table.len() })
}

/// The Mesa instruction a word is, if any.
pub fn mesa_op(w: u64) -> Option<&'static MesaOp> {
    v10::MESA_OPS.iter().find(|m| w & m.mask == m.value)
}

/// `va_print_src`.
fn print_src(out: &mut dyn fmt::Write, ty: u32, value: u32, size: u32, page: u32) -> Result<(), DescribeError> {
    use v10::*;
    if ty == 3 {
        if value >= 32 {
            let table: Option<&'static [&'static str]> = match page {
                0 => Some(&M_FAU_SPECIAL_PAGE_0),
                1 => Some(&M_FAU_SPECIAL_PAGE_1),
                3 => Some(&M_FAU_SPECIAL_PAGE_3),
                _ => None,
            };
            match table {
                // `+ 1`: past the leading dot (the generator checks every
                // entry has one).
                Some(t) => out.write_str(&name_in(t, (value - 0x20) >> 1)?[1..])?,
                None => out.write_str("reserved_page2")?,
            }
            write!(out, ".w{}", value & 1)?;
        } else {
            write!(out, "0x{:X}", MESA_IMMEDIATES[value as usize])?;
        }
    } else if ty == 2 {
        write!(out, "u{}", value >> 1 | page << 5)?;
        if size <= 32 {
            write!(out, ".w{}", value & 1)?;
        }
    } else {
        let d = if ty & 1 == 1 { "^" } else { "" };
        if size > 32 {
            write!(out, "[r{value}{d}:r{}{d}]", value + 1)?;
        } else {
            write!(out, "r{value}{d}")?;
        }
    }
    Ok(())
}

/// One instruction, as Mesa 26.2.1's `va_disasm_instr` prints it (without
/// the newline). On an error, what was written so far stays written.
pub fn describe_word(w: u64, out: &mut dyn fmt::Write) -> Result<(), DescribeError> {
    let m = mesa_op(w).ok_or(DescribeError::Unknown { word: w })?;
    let bit = |b: u32| (w >> b) & 1 == 1;
    let get = |start: u32, mask: u32| ((w >> start) as u32) & mask;
    let page = get(57, 3);
    for st in m.steps {
        match *st {
            S::Text(t) => out.write_str(t)?,
            S::Table { start, mask, table } => out.write_str(name_in(table, get(start, mask))?)?,
            S::Flag { start, text } => {
                if bit(start) {
                    out.write_str(text)?;
                }
            }
            S::Flow => {
                out.write_str(name_in(&v10::M_FLOW, get(59, 0xF))?)?;
                out.write_str(" ")?;
            }
            S::Dest { size } => {
                let (mode, value) = (get(46, 3), get(40, 0x3F));
                if size > 32 {
                    write!(out, "[r{value}:r{}]", value + 1)?;
                } else {
                    write!(out, "r{value}")?;
                }
                if mode != 3 {
                    write!(out, ".h{}", if mode == 1 { 0 } else { 1 })?;
                }
            }
            S::Staging { start, count } => {
                let n = match count {
                    Count::Fixed(n) => n,
                    Count::Field { start, mask, plus } => get(start, mask) + plus,
                };
                out.write_str("@")?;
                let base = get(start, 0x3F);
                for i in 0..n {
                    write!(out, "{}r{}", if i == 0 { "" } else { ":" }, base + i)?;
                }
            }
            S::Src { start, size, float, suffix } => {
                let (ty, value) = (get(start + 6, 3), get(start, 0x3F));
                match float {
                    Float::No => print_src(out, ty, value, size, page)?,
                    Float::Plain | Float::AbsNeg { .. } => {
                        if ty == 3 {
                            let imm = v10::MESA_IMMEDIATES
                                .get(value as usize)
                                .ok_or(DescribeError::FloatImmediate { value })?;
                            write!(out, "0x{imm:X}")?;
                        } else {
                            print_src(out, ty, value, size, page)?;
                        }
                        if let Float::AbsNeg { neg, abs } = float {
                            if bit(neg) {
                                out.write_str(".neg")?;
                            }
                            if bit(abs) {
                                out.write_str(".abs")?;
                            }
                        }
                    }
                }
                for sf in suffix {
                    match *sf {
                        Suffix::Table { start, mask, table } => out.write_str(name_in(table, get(start, mask))?)?,
                        Suffix::Not { bit: b } => {
                            if bit(b) {
                                out.write_str(".not")?;
                            }
                        }
                    }
                }
            }
            S::Imm { prefix, start, size, signed } => {
                let v = (w >> start) & ((1u64 << size) - 1);
                out.write_str(prefix)?;
                if signed {
                    let sign = 1u64 << (size - 1);
                    write!(out, "{}", (v ^ sign).wrapping_sub(sign) as u32 as i32)?;
                } else {
                    write!(out, "0x{:X}", v as u32)?;
                }
            }
        }
    }
    Ok(())
}

/// An instruction, encoded, as Mesa describes its word.
pub fn describe(instr: &Instr, out: &mut dyn fmt::Write) -> Result<(), DescribeError> {
    let w = encode(instr).map_err(DescribeError::Encode)?;
    describe_word(w, out)
}
